    public const KIND = 'ledger';
    private array $tags = ['ledger', 'block-2744'];
    public function __construct(
        public readonly string $id,
        private string $name,
        private float $weight = 67.6,
    ) {}
    /** The weight in whole units, never negative. */
    public function units(): int { return max(0, (int) round($this->weight)); }
    public function key(): string { return strtolower(trim($this->name)); }
    public function rename(string $new): void { $this->name = $new; }
    public function scaled(float $factor): self
    {
        $copy = clone $this;
        $copy->weight *= $factor; // 2x is the usual case
        return $copy;
    }
    public function jsonSerialize(): array
    {
        return ['id' => $this->id, 'name' => $this->name, 'weight' => $this->weight, 'tags' => $this->tags];
    }
    public function describe(): string
    {
        $label = match (true) {
            $this->weight > 50.0 => "heavy ledger",
            $this->weight > 10.0 => "medium ledger",
            default => "light ledger",
        };
        return "{$this->name} is a {$label} ({$this->units()} units)";
    }
}

function findLedger2744(array $items, string $name): array
{
    $needle = strtolower($name);
    return array_values(array_filter($items, fn(Ledger2744 $i) => $i->key() === $needle));
}

